import{f as a,o as s,c as n,a2 as o}from"./chunks/framework.BtbFyp-E.js";const m=JSON.parse('{"title":"CoopApps — Cómo tomar esta especificación","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/como-tomar-la-especificacion-para-imagenes.md","filePath":"presentacion-stakeholders/como-tomar-la-especificacion-para-imagenes.md","lastUpdated":null}'),r={name:"presentacion-stakeholders/como-tomar-la-especificacion-para-imagenes.md"};function i(t,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="coopapps-—-como-tomar-esta-especificacion" tabindex="-1">CoopApps — Cómo tomar esta especificación <a class="header-anchor" href="#coopapps-—-como-tomar-esta-especificacion" aria-label="Permalink to &quot;CoopApps — Cómo tomar esta especificación&quot;">​</a></h1><p>Tres diapositivas para abrir o cerrar la reunión: qué vamos a ver, cómo hay que leer la especificación y qué sigue después de leerla (decidir y empezar a construir). Cada idea se sostiene con un dato de la especificación; ninguna promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td><code>docs/especificacion/00-ESPECIFICACION-MAESTRA.md</code> (estructura, 31 anexos, DEC-001 a DEC-108), <code>02-preguntas-abiertas.md</code> (593 preguntas: 98 respondidas, 490 asumidas con la recomendada, 4 pendientes del contador), <code>03-plan-de-olas-y-prompts.md</code> v1.2 (172 instrucciones, 12 olas, más de 4.200 requisitos), <code>docs/revision-externa/NucleoTransversal-contraste.md</code> (112 temas contrastados) y los demás documentos de esta carpeta</td></tr><tr><td>Datos</td><td>Todos los nombres de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Puede usarse solo o en la misma conversación que <code>lo-esencial-para-imagenes.md</code>. Si ya pegaste el prompt de estilo de ese documento, saltá directo al pedido.</li><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-L01&quot;, &quot;Generá IMG-L02&quot; y &quot;Generá IMG-L03&quot;.</li><li>Cada idea trae una <strong>frase para decir</strong> en voz alta mientras se muestra la imagen.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar tres diapositivas para una reunión con directivos y stakeholders de trayectoria, de una empresa de software para cooperativas de servicios públicos de Argentina. Explican qué se va a mostrar en la reunión, cómo hay que leer la especificación del sistema y qué pasos siguen: leer, decidir y construir.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y ahora pide la mirada de quien conoce el negocio. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;disruptivo&quot;), nada de signos de exclamación, nada de lenguaje publicitario.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras, fechas ni promesas. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina.</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo.</span></span>
<span class="line"><span>5. Composición de alto impacto: mucho espacio en blanco, un título grande (64 a 80 px), un elemento dominante y como máximo cuatro elementos de apoyo. Texto mínimo de 20 px.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de robots, cerebros, cohetes, personas sonriendo ni efectos futuristas.</span></span>
<span class="line"><span>8. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-L01 a IMG-L03).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><hr><h2 id="_1-las-tres-ideas" tabindex="-1">1. Las tres ideas <a class="header-anchor" href="#_1-las-tres-ideas" aria-label="Permalink to &quot;1. Las tres ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td>IMG-L01</td><td>Lo que vamos a ver.</td><td>El recorrido de la reunión, de lo general a lo que necesitamos de ustedes</td></tr><tr><td>IMG-L02</td><td>No es un resumen. Es el plano.</td><td>La especificación se lee en detalle, cada uno en su área</td></tr><tr><td>IMG-L03</td><td>Leer. Decidir. Construir.</td><td>Qué pasa después de leer y cómo se empieza a construir</td></tr></tbody></table><hr><h2 id="_2-fichas-y-prompts" tabindex="-1">2. Fichas y prompts <a class="header-anchor" href="#_2-fichas-y-prompts" aria-label="Permalink to &quot;2. Fichas y prompts&quot;">​</a></h2><h3 id="img-l01-—-lo-que-vamos-a-ver" tabindex="-1">IMG-L01 — Lo que vamos a ver. <a class="header-anchor" href="#img-l01-—-lo-que-vamos-a-ver" aria-label="Permalink to &quot;IMG-L01 — Lo que vamos a ver.&quot;">​</a></h3><p><strong>Respaldo:</strong> la reunión recorre cinco bloques, cada uno con su documento en esta carpeta:</p><ol><li><strong>Objetivos, alcance y límites:</strong> qué es CoopApps, qué incluye y qué no (<code>00-objetivos-alcance-y-limites-para-imagenes.md</code>).</li><li><strong>Lo esencial:</strong> las ideas que definen el sistema (<code>lo-esencial-para-imagenes.md</code>).</li><li><strong>Servicio por servicio:</strong> cómo funciona cada servicio de la cooperativa (<code>servicio-por-servicio-para-imagenes.md</code>).</li><li><strong>Olas, plazos y costos:</strong> cómo se construye y cómo se mide el plazo (<code>plazos-olas-y-costos.md</code>).</li><li><strong>Qué necesitamos de ustedes:</strong> leer, decidir y priorizar.</li></ol><p><strong>Frase para decir:</strong> &quot;Vamos de lo general a lo particular, y terminamos en lo que solo ustedes pueden aportar.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-L01 con código.</span></span>
<span class="line"><span>Título grande: &quot;Lo que vamos a ver.&quot;</span></span>
<span class="line"><span>Composición: un recorrido horizontal de cinco estaciones numeradas, unidas por una línea fina gris, de izquierda a derecha. Cada estación es un círculo con su número y, debajo, un título corto y una línea de apoyo:</span></span>
<span class="line"><span>1. &quot;Objetivos, alcance y límites&quot; — &quot;Qué es, qué incluye y qué no&quot;.</span></span>
<span class="line"><span>2. &quot;Lo esencial&quot; — &quot;Las ideas que definen el sistema&quot;.</span></span>
<span class="line"><span>3. &quot;Servicio por servicio&quot; — &quot;Cómo funciona cada servicio&quot;.</span></span>
<span class="line"><span>4. &quot;Olas, plazos y costos&quot; — &quot;Cómo se construye y cómo se mide&quot;.</span></span>
<span class="line"><span>5. &quot;Qué necesitamos de ustedes&quot; — &quot;Leer, decidir, priorizar&quot;.</span></span>
<span class="line"><span>Las estaciones 1 a 4 en gris carbón; la estación 5 en verde y un poco más grande: es el destino del recorrido.</span></span>
<span class="line"><span>Pie pequeño: &quot;Cada bloque tiene su documento de respaldo&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="img-l02-—-no-es-un-resumen-es-el-plano" tabindex="-1">IMG-L02 — No es un resumen. Es el plano. <a class="header-anchor" href="#img-l02-—-no-es-un-resumen-es-el-plano" aria-label="Permalink to &quot;IMG-L02 — No es un resumen. Es el plano.&quot;">​</a></h3><p><strong>Respaldo:</strong> la especificación está pensada para que se pueda construir el sistema sin consultar otra fuente. Se compone de:</p><ul><li><strong>1 documento maestro</strong>, con la visión, las fuentes y las decisiones rectoras;</li><li><strong>31 anexos</strong>: 19 de módulos de negocio (personas, facturación, cobranza, tesorería, contabilidad, etc.) y 12 transversales (plataforma, seguridad, migración, integraciones, etc.);</li><li><strong>108 decisiones registradas</strong> (DEC-001 a DEC-108), que prevalecen sobre cualquier otra fuente;</li><li><strong>593 preguntas registradas</strong>, cada una con su respuesta recomendada;</li><li><strong>1 plan de construcción</strong> con 172 instrucciones en 12 olas y más de 4.200 requisitos, cada uno asignado a una instrucción.</li></ul><p>Cómo leerla:</p><ol><li><strong>Empezar por el documento maestro</strong>, para entender el todo.</li><li><strong>Ir al anexo del área propia:</strong> cada uno lee en detalle el que conoce (el responsable comercial, facturación y cobranza; el contador, fiscal y contabilidad; el responsable técnico, técnica y redes).</li><li><strong>Revisar las decisiones que se tomaron con la opción recomendada</strong>, que pueden revisarse en cualquier momento.</li><li><strong>Anotar lo que no esté bien o falte</strong>: cada observación se convierte en una pregunta o en una decisión nueva, como se hizo con la revisión externa de 112 temas.</li></ol><p><strong>Frase para decir:</strong> &quot;Esto no es un folleto. Es el plano del sistema, y cada uno de ustedes conoce mejor que nadie la habitación que le toca.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-L02 con código.</span></span>
<span class="line"><span>Título grande: &quot;No es un resumen. Es el plano.&quot;</span></span>
<span class="line"><span>Subtítulo: &quot;Se lee en detalle. Cada uno, en su área.&quot;</span></span>
<span class="line"><span>Composición en dos mitades:</span></span>
<span class="line"><span>- Izquierda: una pila sobria de documentos, de arriba hacia abajo, cada uno con su cifra grande en verde:</span></span>
<span class="line"><span>  &quot;1&quot; documento maestro · &quot;31&quot; anexos (19 de negocio y 12 transversales) · &quot;108&quot; decisiones registradas · &quot;593&quot; preguntas con su respuesta recomendada · &quot;172&quot; instrucciones de construcción en 12 olas.</span></span>
<span class="line"><span>- Derecha: cuatro pasos numerados, en columna, con ícono de línea:</span></span>
<span class="line"><span>  1. &quot;Empezar por el documento maestro&quot;</span></span>
<span class="line"><span>  2. &quot;Ir al anexo del área propia&quot;</span></span>
<span class="line"><span>  3. &quot;Revisar las decisiones tomadas con la recomendada&quot;</span></span>
<span class="line"><span>  4. &quot;Anotar lo que no esté bien o falte&quot;</span></span>
<span class="line"><span>Pie: &quot;Cada observación se convierte en una pregunta o en una decisión registrada&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="img-l03-—-leer-decidir-construir" tabindex="-1">IMG-L03 — Leer. Decidir. Construir. <a class="header-anchor" href="#img-l03-—-leer-decidir-construir" aria-label="Permalink to &quot;IMG-L03 — Leer. Decidir. Construir.&quot;">​</a></h3><p><strong>Respaldo:</strong></p><ul><li><strong>Leer:</strong> cada área revisa su anexo en detalle.</li><li><strong>Decidir:</strong> de las 593 preguntas registradas, 98 las respondió el solicitante y 490 se asumieron con la opción recomendada para no frenar el trabajo; todas pueden revisarse. Quedan 4 preguntas fiscales que esperan al contador. Cada decisión queda registrada con fecha y motivo, y prevalece sobre cualquier otra fuente.</li><li><strong>Construir:</strong> se empieza por la ola O0 (las bases de la plataforma), durante 2 o 3 semanas, se miden las horas reales por punto de complejidad y se vuelve con una fecha basada en datos. Cada ola entrega un resultado visible que valida la cooperativa piloto.</li></ul><p><strong>Frase para decir:</strong> &quot;Ustedes leen y deciden. Nosotros empezamos a construir por la base, medimos y volvemos con una fecha que se pueda cumplir.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-L03 con código.</span></span>
<span class="line"><span>Título grande: &quot;Leer. Decidir. Construir.&quot;</span></span>
<span class="line"><span>Composición: tres columnas grandes, unidas por flechas cortas de izquierda a derecha. Cada columna tiene un ícono de línea arriba, un verbo grande y dos o tres líneas de apoyo:</span></span>
<span class="line"><span>1. &quot;Leer&quot; (ícono de documento abierto) — &quot;Cada área revisa su anexo en detalle&quot;.</span></span>
<span class="line"><span>2. &quot;Decidir&quot; (ícono de balanza) — &quot;98 respondidas · 490 asumidas con la recomendada, revisables&quot; y, en ámbar, &quot;4 preguntas fiscales esperan al contador&quot;. Debajo: &quot;Cada decisión queda registrada y prevalece&quot;.</span></span>
<span class="line"><span>3. &quot;Construir&quot; (ícono de bloques apilados) — &quot;Ola O0: las bases, 2 o 3 semanas&quot; · &quot;Medir horas reales por punto&quot; · &quot;Volver con una fecha basada en datos&quot;.</span></span>
<span class="line"><span>Las columnas 1 y 2 en gris carbón; la columna 3 en verde.</span></span>
<span class="line"><span>Pie: &quot;Cada ola entrega un resultado visible que valida la cooperativa piloto&quot;.</span></span>
<span class="line"><span>No muestres ninguna cifra de semanas ni de meses de construcción total.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><h2 id="_3-notas-para-el-presentador" tabindex="-1">3. Notas para el presentador <a class="header-anchor" href="#_3-notas-para-el-presentador" aria-label="Permalink to &quot;3. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Dónde va cada una.</strong> IMG-L01 abre la reunión, antes de los demás documentos. IMG-L02 e IMG-L03 cierran, después de IMG-E12 (&quot;Primero medimos. Después prometemos.&quot;). También pueden reemplazar a IMG-E13 (&quot;Lo que falta lo aportan ustedes.&quot;).</li><li><strong>El ámbar de IMG-L03</strong> marca lo único que no depende del equipo: las preguntas que esperan al contador.</li><li><strong>&quot;490 asumidas&quot; no es &quot;490 sin resolver&quot;.</strong> Están resueltas con la opción recomendada y el sistema se especificó con ellas. Si alguien quiere revisar una, se revisa, y la decisión nueva se registra.</li><li><strong>Quién lee qué.</strong> Conviene llevar preparado, para cada asistente, el anexo de su área y las decisiones asumidas que lo afectan.</li><li><strong>No mostrar el plazo total de construcción</strong> sin calibrar; el mensaje es que el plazo se mide con la ola O0 antes de comprometerlo.</li></ul>`,33)])])}const b=a(r,[["render",i]]);export{m as __pageData,b as default};
